Your expense tracker is below. Add an item, pick a category and amount, and the totals update as you go. Entries may not be kept after you close this chat, so note down your final total.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Segoe UI, sans-serif; margin: 0; padding: 12px; color: #222; }
  h2 { margin: 0 0 10px; font-size: 18px; }
  .row { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; }
  input, select, button { padding: 7px 9px; font-size: 14px; border: 1px solid #bbb; border-radius: 6px; }
  input.name { flex: 2; min-width: 110px; }
  input.amt { flex: 1; min-width: 80px; }
  button { background: #2b6cb0; color: #fff; border-color: #2b6cb0; cursor: pointer; }
  button.del { background: none; color: #c53030; border: none; padding: 2px 6px; }
  .total { font-size: 20px; font-weight: 600; margin: 8px 0; }
  .bar { height: 8px; background: #e2e8f0; border-radius: 4px; overflow: hidden; margin-top: 3px; }
  .fill { height: 100%; background: #2b6cb0; }
  .cat { margin-bottom: 8px; font-size: 13px; }
  .cat span.r { float: right; }
  ul { list-style: none; padding: 0; margin: 10px 0 0; }
  li { display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #eee; font-size: 14px; }
  .muted { color: #777; font-size: 12px; }
  .budget { display: flex; gap: 6px; align-items: center; margin-bottom: 6px; font-size: 13px; }
</style>
</head>
<body>
  <h2>Monthly expenses</h2>

  <div class="budget">
    <label for="budget">Monthly budget (₹)</label>
    <input id="budget" class="amt" type="number" min="0" placeholder="e.g. 50000">
  </div>

  <div class="row">
    <input id="name" class="name" type="text" placeholder="What for?">
    <select id="cat">
      <option>Food</option>
      <option>Rent</option>
      <option>Travel</option>
      <option>Bills</option>
      <option>Shopping</option>
      <option>Health</option>
      <option>Other</option>
    </select>
    <input id="amt" class="amt" type="number" min="0" placeholder="₹ Amount">
    <button id="add" type="button">Add</button>
  </div>

  <div class="total">Total: <span id="total">₹0</span></div>
  <div id="left" class="muted"></div>
  <div id="cats" style="margin-top:10px"></div>
  <ul id="list"></ul>
  <div id="empty" class="muted">No expenses yet. Add your first one above.</div>

<script>
  var items = [];
  try { items = JSON.parse(localStorage.getItem("exp") || "[]"); } catch (e) { items = []; }

  function money(n) { return "₹" + Number(n).toLocaleString("en-IN"); }
  function save() { try { localStorage.setItem("exp", JSON.stringify(items)); } catch (e) {} }

  function render() {
    var total = 0, byCat = {};
    items.forEach(function (it) {
      total += it.amt;
      byCat[it.cat] = (byCat[it.cat] || 0) + it.amt;
    });
    document.getElementById("total").textContent = money(total);

    var b = parseFloat(document.getElementById("budget").value);
    var left = document.getElementById("left");
    if (b > 0) {
      left.textContent = total <= b ? money(b - total) + " left of your budget" : money(total - b) + " over your budget";
      left.style.color = total <= b ? "#2f855a" : "#c53030";
    } else { left.textContent = ""; }

    var catsHtml = "";
    Object.keys(byCat).sort(function (a, c) { return byCat[c] - byCat[a]; }).forEach(function (k) {
      var pct = total ? Math.round(byCat[k] / total * 100) : 0;
      catsHtml += '<div class="cat">' + k + '<span class="r">' + money(byCat[k]) + ' (' + pct + '%)</span><div class="bar"><div class="fill" style="width:' + pct + '%"></div></div></div>';
    });
    document.getElementById("cats").innerHTML = catsHtml;

    var list = document.getElementById("list");
    list.innerHTML = "";
    items.forEach(function (it, i) {
      var li = document.createElement("li");
      var left = document.createElement("span");
      left.textContent = it.name + " · " + it.cat;
      var right = document.createElement("span");
      right.textContent = money(it.amt) + " ";
      var d = document.createElement("button");
      d.className = "del"; d.type = "button"; d.textContent = "✕";
      d.onclick = function () { items.splice(i, 1); save(); render(); };
      right.appendChild(d);
      li.appendChild(left); li.appendChild(right);
      list.appendChild(li);
    });
    document.getElementById("empty").style.display = items.length ? "none" : "block";
  }

  document.getElementById("add").onclick = function () {
    var name = document.getElementById("name").value.trim();
    var amt = parseFloat(document.getElementById("amt").value);
    if (!name || !(amt > 0)) return;
    items.push({ name: name, cat: document.getElementById("cat").value, amt: amt });
    document.getElementById("name").value = "";
    document.getElementById("amt").value = "";
    save(); render();
  };
  document.getElementById("budget").oninput = render;
  render();
</script>
</body>
</html>
```

